import random
import ipaddress
import time

from core import helpers

def simulate_load():
  loads = [200, 300, 400, 500]
  count = 0
  limit = random.choice(loads)
  while True:
    time.sleep(0.1)
    count += 1
    if count > limit:
      return

def get_network(addr, style='cidr'):
  try:
    if style == 'cidr':
      return str(ipaddress.ip_network(addr))
    else:
      return str(ipaddress.ip_network(addr).netmask)
  except:
    return 'Could not identify network'

def is_port(port):
  if isinstance(port, int):
    if port >= 0 and port <= 65535:
      return True
  return False

def allowed_cmds(cmd):
  if helpers.is_level_easy():
    return True
  elif helpers.is_level_hard():
    if cmd.startswith(('echo', 'ps' 'whoami', 'tail')):
      return True
  return False

def strip_dangerous_characters(cmd):
  if helpers.is_level_easy():
    return cmd
  elif helpers.is_level_hard():
    return cmd.replace(';','').replace('&', '')
  return cmd

def check_creds(username, password, real_password):
  if username != 'admin':
    return (False, 'Username is invalid')

  if password == real_password:
    return (True, 'Password Accepted.')

  return (False, 'Password Incorrect')

def on_denylist(query):
  normalized_query = ''.join(query.split())
  queries = [
    'query{systemHealth}',
    '{systemHealth}'
  ]

  if normalized_query in queries:
    return True
  return False

def operation_name_allowed(operation_name):
  opnames_allowed = ['CreatePaste', 'CreateUser', 'EditPaste', 'getPastes', 'UploadPaste', 'ImportPaste']
  if operation_name in opnames_allowed:
    return True
  return False

def depth_exceeded(depth):
  depth_allowed = config.MAX_DEPTH
  if depth > depth_allowed:
    return True
  return False

def cost_exceeded(qry_fields):
  total_cost_allowed = config.MAX_COST
  total_query_cost   = 0

  field_cost = {
    'systemUpdate':10,
  }

  for field in qry_fields:
    if field in field_cost:
      total_query_cost += field_cost[field]

  if total_query_cost > total_cost_allowed:
    return True

  return False"},{"caminho":"core/view_override.py","conteudo_utf8":"import json
import traceback
import inspect

from core.models import Audit
from functools import partial
from flask import Response, request
from flask_graphql import GraphQLView
from rx import AnonymousObservable
from graphql_server import (
    HttpQueryError,
    run_http_query,
    FormattedResult
)
from graphql import GraphQLError
from graphql.error import format_error as format_graphql_error
from graphql_ws.gevent import GeventConnectionContext
from graphql_ws.base_sync import BaseSyncSubscriptionServer
from graphql_ws.base import ConnectionClosedException

def format_custom_error(error):
    try:
        message = str(error)
    except UnicodeEncodeError:
        message = error.message.encode("utf-8")

    formatted_error = {"message": message}

    if isinstance(error, GraphQLError):
        if error.locations is not None:
            formatted_error["locations"] = [
                {"line": loc.line, "column": loc.column} for loc in error.locations
            ]

        if error.path is not None:
            formatted_error["path"] = error.path

        if error.extensions is not None:
            formatted_error["extensions"] = error.extensions

        # A user who has not yet altered their cookie to bypass the GraphiQL protection will see the debug information and may get bamboozled
        # Do not show tracing error the first time a user hits the GraphiQL endpoint.
        if 'GraphiQL Access Rejected' not in message:
            if 'extensions' not in formatted_error:
                formatted_error['extensions'] = {}

            # Get some stack traces and caller file information
            frame = inspect.currentframe()
            caller_frame = inspect.stack()[0]
            caller_filename_full = caller_frame.filename

            formatted_error['extensions']['exception'] = {}
            formatted_error['extensions']['exception']['stack'] = traceback.format_stack(frame)
            formatted_error['extensions']['exception']['debug'] = traceback.format_exc()
            formatted_error['extensions']['exception']['path'] = caller_filename_full

    return formatted_error

def format_execution_result(execution_result, format_error,):
    status_code = 200
    if execution_result:
        target_result = None

        def override_target_result(value):
            nonlocal target_result
            target_result = value

        if isinstance(execution_result, AnonymousObservable):
            target = execution_result.subscribe(on_next=lambda value: override_target_result(value))
            target.dispose()
            response = target_result
        elif execution_result.invalid:
            status_code = 400
            response = execution_result.to_dict(format_error=format_error)
        else:
            response = execution_result.to_dict(format_error=format_error)
    else:
        response = None
    return FormattedResult(response, status_code)

def encode_execution_results(execution_results, format_error, is_batch,encode):
    responses = [
        format_execution_result(execution_result, format_error)
        for execution_result in execution_results
    ]
    result, status_codes = zip(*responses)
    status_code = max(status_codes)

    if not is_batch:
        result = result[0]

    return encode(result), status_code

class OverriddenView(GraphQLView):
    def dispatch_request(self):
        try:
            request_method = request.method.lower()
            data = self.parse_body()

            show_graphiql = request_method == 'get' and self.should_display_graphiql()
            catch = show_graphiql
            pretty = self.pretty or show_graphiql or request.args.get('pretty')

            extra_options = {}
            executor = self.get_executor()
            if executor:
                # We only include it optionally since
                # executor is not a valid argument in all backends
                extra_options['executor'] = executor

            execution_results, all_params = run_http_query(
                self.schema,
                request_method,
                data,
                query_data=request.args,
                batch_enabled=self.batch,
                catch=catch,
                backend=self.get_backend(),

                # Execute options
                root=self.get_root_value(),
                context=self.get_context(),
                middleware=self.get_middleware(),
                **extra_options
            )

            result, status_code = encode_execution_results(
                execution_results,
                is_batch=isinstance(data, list),
                format_error=self.format_error,
                encode=partial(self.encode, pretty=pretty)

            )

            if show_graphiql:
                return self.render_graphiql(
                    params=all_params[0],
                    result=result
                )

            return Response(
                result,
                status=status_code,
                content_type='application/json'
            )

        except HttpQueryError as e:
            return Response(
                self.encode({
                    'errors': [self.format_error(e)]
                }),
                status=e.status_code,
                headers=e.headers,
                content_type='application/json'
            )

